# -*- coding: utf-8 -*-
import os
import tempfile


class ArtifactManager(object):
    """Resolves download, screenshot, trace, and video artifact directories."""

    def __init__(self, download_suffix="taf_playwright_download", screenshot_suffix="taf_playwright_screenshot"):
        self.download_suffix = download_suffix
        self.screenshot_suffix = screenshot_suffix

    def ensure_dir(self, target):
        if not os.path.exists(target):
            os.makedirs(target)
        return target

    def download_dir(self, download_dir=None):
        if download_dir and download_dir != "/":
            return self.ensure_dir(download_dir)
        return self.ensure_dir(tempfile.mkdtemp(suffix=self.download_suffix))

    def screenshot_dir(self, download_dir, screenshot_dir=None):
        if screenshot_dir:
            return self.ensure_dir(screenshot_dir)
        return self.ensure_dir(os.path.join(download_dir, self.screenshot_suffix))
